/**
 * Phase 2.97 closure audit, Check 3 (review agent finding — "presence in an
 * Experience is not equivalent to psychological centrality"): the
 * referent(s) a memory's outcome should attribute to, and each one's
 * attribution weight. `NeedOutcomeRecord` itself carries no subject (it is
 * a whole-Experience-level realized effect, `{needId, result}` only) — the
 * PRE-FIX code closed that gap by attributing wholly to the option's own
 * subject, silently treating every OTHER participant as equally (i.e.
 * zero-vs-one, not weighted) irrelevant. The fix consumes
 * `MemoryEpisode.conceptSalience` (Phase 2.5b/c's already-computed
 * character-relative salience, threaded onto the memory record by
 * `cycle.ts` — see that field's own doc comment).
 *
 * Weights are each participant's salience NORMALIZED against the total
 * salience of every participant with any — an earlier, un-normalized draft
 * of this function (using raw salience directly as the weight) was
 * actually run against the full suite and DID break Experiments D/E/J:
 * their single-participant memories' subject concept legitimately has
 * salience z < 1 (attention/perception, a different quantity from "which
 * referent among several present ones does this outcome belong to"), so
 * using it directly as an absolute weight silently shrank every already-
 * calibrated situational contribution. Normalizing means a
 * single-participant memory —
 * the "easy case," still the only case this scenario's real pipeline ever
 * produces — ALWAYS gets weight exactly 1 regardless of that participant's
 * own absolute salience score, exactly preserving the pre-fix behavior;
 * only a GENUINELY multi-participant memory ever splits weight across
 * referents, proportional to their relative salience (a highly-salient
 * Glen contributes more than a merely-present Priya from the SAME memory).
 * Falls back to the pre-fix "attribute wholly to the option's own subject,
 * weight 1" behavior only when NO participant has any salience data at all
 * (`salienceMode: 'legacy'` memories, and any fixture built before this
 * field existed, both leave `conceptSalience` empty).
 */
function attributedReferents(episode: MemoryEpisode, option: Option): readonly { readonly referent: ReferentKey; readonly weight: Rational }[] {
  const salient = episode.participants
    .map((p) => ({ referent: p as ReferentKey, salience: episode.conceptSalience.get(p) ?? Rational.ZERO }))
    .filter((e) => !e.salience.isZero());
  if (salient.length === 0) return [{ referent: subjectReferent(option), weight: Rational.ONE }];
  const totalSalience = salient.reduce((acc, e) => acc.add(e.salience), Rational.ZERO);
  return salient.map((e) => ({ referent: e.referent, weight: e.salience.div(totalSalience) }));
}

/**
 * SituationalEvidence signals from a retrieved memory's realized Need
 * outcomes (Brief §32, "recent supportive/unsupportive history"): one
 * signal per (memory, NeedOutcome, attributed referent) with nonzero,
 * mapped, nonzero-weighted result — see `attributedReferents` above for how
 * referent attribution and its weight are now derived. EvidenceBasis is
 * exactly `{[episode.experienceId]: 1}` — directly off existing
 * `MemoryEpisode` data, no retrofit (decision 6); the correlation
 * consolidator only cares about provenance identity, not attribution
 * weight, so every referent's signal from the same memory legitimately
 * shares one basis.
 */
export function situationalMemorySignals(
  option: Option,
  retrieved: readonly ScoredMemory[],
  mapping: NeedMotiveChannelMapping,
): RawCognitiveSignal[] {
  const signals: RawCognitiveSignal[] = [];
  for (const scored of retrieved) {
    const episode = scored.record.memory;
    if (!memoryIsRelevant(episode, option)) continue;
    const basis: EvidenceBasis = evidenceBasisOf([[episode.experienceId, Rational.ONE]]);
    const referents = attributedReferents(episode, option);
    for (const outcome of episode.needOutcomes) {
      if (outcome.result.isZero()) continue;
      const motiveChannel = mapping.get(outcome.needId);
      if (!motiveChannel) continue;
      for (const { referent, weight } of referents) {
        const signedStrength = outcome.result.mul(weight);
        if (signedStrength.isZero()) continue;
        signals.push({
          signalId: `memory:${episode.memoryId}:${outcome.needId}:${option.actionDef.actionKey}:${referent}`,
          optionKey: option.actionDef.actionKey,
          motiveChannel,
          referent,
          sourceRole: 'SituationalEvidence',
          signedStrength,
          basis,
        });
      }
    }
  }
  return signals;

  // Phase 2.97 closure audit, Check 3 (review agent finding): "presence in
  // an Experience is not equivalent to psychological centrality." A memory
  // with Glen highly salient and Priya merely present must attribute more
  // to Glen's nucleus than to Priya's, not treat the two identically.
  it('a multi-participant memory attributes referent contribution by SemanticExperience salience, not bare participants membership', () => {
    const PRIYA = conceptKey('person.priya');
    const retrieved = [
      fakeMemory({
        participants: [GLEN, PRIYA],
        conceptSalience: new Map([
          [GLEN, ratOf(4, 5)], // highly salient
          [PRIYA, ratOf(1, 5)], // merely present
        ]),
      }),
    ];
    const signals = situationalMemorySignals(option, retrieved, needMapping);
    expect(signals).toHaveLength(2);
    const glenSignal = signals.find((s) => s.referent === GLEN)!;
    const priyaSignal = signals.find((s) => s.referent === PRIYA)!;
    expect(glenSignal).toBeDefined();
    expect(priyaSignal).toBeDefined();
    // needOutcomes[0].result = 2/5; weighted by salience: Glen = 2/5*4/5 = 8/25, Priya = 2/5*1/5 = 2/25.
    expect(glenSignal.signedStrength.equals(ratOf(8, 25))).toBe(true);
    expect(priyaSignal.signedStrength.equals(ratOf(2, 25))).toBe(true);
    expect(glenSignal.signedStrength.gt(priyaSignal.signedStrength)).toBe(true);
    // Both signals share the same memory's EvidenceBasis (same provenance,
    // different attribution) — correlation consolidation cares about
    // provenance, not which referent a signal was attributed to.
    expect([...glenSignal.basis.weights.entries()]).toEqual([...priyaSignal.basis.weights.entries()]);
  });

  it('an incidental object present in the memory but never a participant gets no referent-attribution signal, even if it had salience', () => {
    const LAMP = conceptKey('object.lamp');
    const retrieved = [
      fakeMemory({
        participants: [GLEN], // the lamp is not a participant, however salient it might be perceived
        conceptSalience: new Map([
          [GLEN, ratOf(1, 2)],
          [LAMP, ratOf(9, 10)],
        ]),
      }),
    ];
    const signals = situationalMemorySignals(option, retrieved, needMapping);
    expect(signals.every((s) => s.referent !== LAMP)).toBe(true);
  });

  it('falls back to attributing wholly to the option\'s own subject when no participant has any recorded salience (legacy/pre-fix memories)', () => {
    const retrieved = [fakeMemory({ participants: [GLEN], conceptSalience: new Map() })];
    const signals = situationalMemorySignals(option, retrieved, needMapping);
    expect(signals).toHaveLength(1);
    expect(signals[0].referent).toBe(GLEN);
    expect(signals[0].signedStrength.equals(ratOf(2, 5))).toBe(true); // unweighted, exactly the pre-fix value
  });
});

/** attribution-production/0.1-candidate; source/PRJ and recalled-operand admission remain upstream. */
import {prepareFocalPositionPairAttributionUse} from './retainedAttributionUse';
import {canonicalEncode,text,typedIdentifier} from '../substrate/canonicalEncoding';
type Arguments=Parameters<typeof prepareFocalPositionPairAttributionUse>;
export interface AttributionProductionContext {readonly observer:string;readonly character:string;readonly at:bigint;readonly focal:{readonly observer:string;readonly consequence:bigint;readonly sourceAt:bigint}|null}
export interface AttributionProductionView {readonly opaque:'attribution-production-view'}
interface Result {readonly observer:string;readonly character:string;readonly consequence:bigint;readonly at:bigint;readonly transformationVersion:'attribution-production/0.1-candidate';readonly disposition:'Supported'|'Unavailable';readonly consumed:readonly {readonly acquisition:bigint;readonly unit:string}[];readonly targets:readonly {readonly acquisition:bigint;readonly unit:string}[]}
const results=new WeakMap<object,Result|null>();
/** Null operands mean actual incomplete grouping/recollection, never fabricated trials. */
export function prepareAttributionProduction(context:AttributionProductionContext,operands:()=>Arguments|null):AttributionProductionView{
 if(typeof context.at!=='bigint'||context.at<0n||typeof context.observer!=='string'||!context.observer||typeof context.character!=='string'||!context.character)throw Error('ATTRIBUTION_PRODUCTION_SUBJECT');
 canonicalEncode(typedIdentifier(1000,text(context.observer)));canonicalEncode(typedIdentifier(1002,text(context.character)));
 const token=Object.freeze({opaque:'attribution-production-view' as const});
 if(context.focal===null){results.set(token,null);return token;}
 if(context.focal.observer!==context.observer||typeof context.focal.consequence!=='bigint'||context.focal.consequence<0n||typeof context.focal.sourceAt!=='bigint'||context.focal.sourceAt<0n||context.focal.sourceAt>=context.at)throw Error('ATTRIBUTION_PRODUCTION_FOCAL');
 const holder={observer:context.observer,character:context.character,consequence:context.focal.consequence,at:context.at,transformationVersion:'attribution-production/0.1-candidate' as const},args=operands();
 let disposition:Result['disposition']='Unavailable',consumed:Result['consumed']=[],targets:Result['targets']=[];
 if(args!==null){if(args[0].now!==holder.at)throw Error('ATTRIBUTION_PRODUCTION_INSTANT');const target={...args[0].trials[args[0].focalTrial].motion.end.address},owner=prepareFocalPositionPairAttributionUse(...args);try{const value=owner.finish(owner.evaluate());disposition=value.assessment.kind;consumed=value.consumed;if(disposition==='Supported'){if(!consumed.some(c=>c.acquisition===target.acquisition&&c.unit===target.unit))throw Error('ATTRIBUTION_PRODUCTION_TARGET');targets=[{...target}];}}finally{owner.close();}}
 results.set(token,structuredClone({...holder,disposition,consumed,targets}));return token;
}
export function produceAttributionResult(view:AttributionProductionView,allocate:()=>bigint){const value=results.get(view);if(value===undefined)throw Error('ATTRIBUTION_PRODUCTION_VIEW');results.delete(view);if(value===null)return {kind:'NoConsequence' as const};const resultId=allocate();if(typeof resultId!=='bigint'||resultId<0n)throw Error('ATTRIBUTION_PRODUCTION_ALLOCATION');return {kind:'Result' as const,result:{resultId,...structuredClone(value)}};}
export const closeAttributionProduction=(view:AttributionProductionView)=>{results.delete(view);};

